{"styles":{"elements":{"link":{"color":{"text":"var(--wp--preset--color--accent-1)"}},"caption":{"color":{"text":"var(--wp--preset--color--contrast)"}},"button":{"color":{"text":"var(--wp--preset--color--base)","background":"var(--wp--preset--color--accent-2)"},"typography":{"fontWeight":"500","letterSpacing":"-0.36px","textTransform":"uppercase"}},"heading":{"color":{"text":"var(--wp--preset--color--contrast)"},"typography":{"fontFamily":"var(--wp--preset--font-family--roboto-slab)","fontWeight":"300","letterSpacing":"-0.5px","lineHeight":"1.2"}},"h2":{"color":{"text":"var(--wp--preset--color--accent-1)"}}},"typography":{"letterSpacing":"0"},"blocks":{"core/navigation":{"typography":{"fontSize":"var(--wp--preset--font-size--large)","letterSpacing":"-0.28px","textTransform":"uppercase"}},"core/post-author":{"typography":{"fontSize":"var(--wp--preset--font-size--small)"}},"core/post-author-name":{"typography":{"fontSize":"var(--wp--preset--font-size--small)"}},"core/post-terms":{"typography":{"fontWeight":"500"}},"core/pullquote":{"typography":{"fontFamily":"var(--wp--preset--font-family--roboto-slab)","fontSize":"var(--wp--preset--font-size--xx-large)","fontWeight":"200"}},"core/search":{"typography":{"textTransform":"uppercase"}},"core/site-tagline":{"typography":{"fontSize":"var(--wp--preset--font-size--large)"}},"core/site-title":{"typography":{"textTransform":"uppercase"}}},"color":{"background":"var(--wp--preset--color--base)"},"css":"/* Dodatkowy CSS (Additional CSS) - dostępność i responsywność */

/* WCAG 2.4.7: widoczny fokus - nigdy samo outline: none */
:where(a, button, input, select, textarea, summary):focus-visible {
 outline: 3px solid var(--wp--preset--color--contrast, #1a1a1a);
 outline-offset: 3px;
}

/* WCAG 2.4.11: element z fokusem nie może chować się pod przyklejonym nagłówkiem */
html {
 scroll-padding-top: 5.5rem; /* dopasowane do wysokości nagłówka strony */
}

/* WCAG 2.5.8: cel dotykowy min. 24 x 24 px */
.wp-block-navigation-item__content,
.wp-block-social-link a,
.wp-block-button__link {
 min-height: 44px;
 min-width: 44px;
 padding-block: 0.5rem;
}

/* Płynna typografia zamiast wielu breakpointów */
h1 {
 font-size: clamp(1.75rem, 1.2rem + 2.5vw, 3rem);
}

/* Mobile first i widok 375 px: kolumny i elementy bez rozjeżdżania się */
@media (max-width: 600px) {
 .wp-block-columns {
 display: flex;
 flex-direction: column;
 gap: 1rem;
 }

 .wp-block-cover {
 min-height: 48vh; /* bezpieczna wysokość na wąskim ekranie 375 px */
 }
}

@media (max-width: 420px) {
 body,
 .wp-site-blocks {
 overflow-x: clip;
 }

 .wp-block-navigation__responsive-container-open,
 .wp-block-button__link {
 max-width: 100%;
 white-space: normal;
 word-break: break-word;
 }
}
"},"settings":{"color":{"palette":{"theme":[{"color":"#FFFFFF","name":"Bazowy","slug":"base"},{"color":"#1a1a1a","name":"Kontrast","slug":"contrast"},{"color":"#0b5d7a","name":"Akcent 1","slug":"accent-1"},{"color":"#14532d","name":"Akcent 2","slug":"accent-2"},{"color":"#6d619e","name":"Akcent 3","slug":"accent-3"},{"color":"#814141","name":"Akcent 4","slug":"accent-4"},{"color":"#FBFAF3","name":"Akcent 5","slug":"accent-5"},{"color":"color-mix(in srgb, currentColor 20%, transparent)","name":"Akcent 6","slug":"accent-6"}]}},"typography":{"fontFamilies":{"theme":[{"name":"Roboto Slab","slug":"roboto-slab","fontFamily":""Roboto Slab", serif","fontFace":[{"fontFamily":""Roboto Slab"","fontStyle":"normal","fontWeight":"100 900","src":["file:./assets/fonts/roboto-slab/RobotoSlab-VariableFont_wght.woff2"]}]},{"name":"Manrope","slug":"manrope","fontFamily":"Manrope, sans-serif","fontFace":[{"src":["file:./assets/fonts/manrope/Manrope-VariableFont_wght.woff2"],"fontWeight":"200 800","fontStyle":"normal","fontFamily":"Manrope"}]}]},"fontSizes":{"theme":[{"fluid":false,"name":"Małe","size":"0.875rem","slug":"small"},{"fluid":{"max":"1.125rem","min":"1rem"},"name":"Średni","size":"1rem","slug":"medium"},{"fluid":{"max":"1.375rem","min":"1.125rem"},"name":"Duży","size":"1.38rem","slug":"large"},{"fluid":{"max":"2rem","min":"1.75rem"},"name":"Bardzo duży","size":"1.75rem","slug":"x-large"},{"fluid":{"max":"2.4rem","min":"2.15rem"},"name":"Bardzo Bardzo Duży","size":"2.15rem","slug":"xx-large"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}

